import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, type JobRow } from './db.ts';

const STEP_MS = 100;
const MAX_ATTEMPTS = 3;
const POLL_MS = 200;
const HEARTBEAT_MS = 1000;

const db = openDatabase();
let stopping = false;

const beat = db.prepare(
  "INSERT INTO heartbeats (name, at) VALUES ('worker', ?) ON CONFLICT(name) DO UPDATE SET at = excluded.at",
);
const claimNext = db.prepare(
  "SELECT * FROM jobs WHERE status = 'queued' AND next_run_at <= ? ORDER BY seq ASC LIMIT 1",
);
const startAttempt = db.prepare(
  "UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, updated_at = ? WHERE seq = ? AND status = 'queued' RETURNING *",
);
const setProgress = db.prepare('UPDATE jobs SET completed = ?, updated_at = ? WHERE seq = ?');
const finishCompleted = db.prepare(
  "UPDATE jobs SET status = 'completed', completed = steps, result_output = ?, error = NULL, updated_at = ? WHERE seq = ?",
);
const finishFailed = db.prepare(
  "UPDATE jobs SET status = 'failed', result_output = NULL, error = 'transient failure', updated_at = ? WHERE seq = ?",
);
const requeue = db.prepare(
  "UPDATE jobs SET status = 'queued', completed = 0, next_run_at = ?, updated_at = ? WHERE seq = ?",
);

const now = () => new Date().toISOString();

function stamp(): void {
  beat.run(Date.now());
}

/**
 * Runs one attempt of a job. Attempt n fails at its first step when n <= failAttempts; the job is
 * retried after 250-2000 ms until MAX_ATTEMPTS attempts have failed.
 */
async function processAttempt(job: JobRow): Promise<void> {
  const attempt = job.attempts;
  if (attempt <= job.fail_attempts) {
    if (attempt >= MAX_ATTEMPTS) {
      finishFailed.run(now(), job.seq);
    } else {
      const delay = 250 + Math.floor(Math.random() * 1751);
      requeue.run(Date.now() + delay, now(), job.seq);
    }
    return;
  }
  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return; // Left as "running"; the next worker start requeues it.
    setProgress.run(step, now(), job.seq);
  }
  finishCompleted.run(job.input.toUpperCase(), now(), job.seq);
}

// A job left "running" by a worker that died is put back in the queue. Only one worker runs at a time.
db.prepare("UPDATE jobs SET status = 'queued', completed = 0, updated_at = ? WHERE status = 'running'").run(now());
stamp();
const heartbeatTimer = setInterval(() => {
  try {
    stamp();
  } catch (e) {
    console.error('heartbeat failed', e);
  }
}, HEARTBEAT_MS);

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

console.log('worker started');
while (!stopping) {
  try {
    const next = claimNext.get(Date.now()) as unknown as JobRow | undefined;
    if (!next) {
      await sleep(POLL_MS);
      continue;
    }
    const started = startAttempt.get(now(), next.seq) as unknown as JobRow | undefined;
    if (started) await processAttempt(started);
  } catch (e) {
    console.error('worker error', e);
    await sleep(POLL_MS);
  }
}

clearInterval(heartbeatTimer);
db.close();
console.log('worker stopped');
process.exit(0);

